module freq_divbyeven #(
    parameter NUM_DIV = 6
) (
    input clk,
    input rst_n,
    output reg clk_div
);

reg [3:0] cnt;
wire [3:0] half_num_div;
reg toggle_clk_div;

assign half_num_div = NUM_DIV >> 1;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 4'b0000;
        toggle_clk_div <= 1'b0;
    end else begin
        if (cnt == half_num_div - 1) begin
            cnt <= 4'b0000;
            toggle_clk_div <= ~toggle_clk_div; 
        end else begin
            cnt <= cnt + 1'b1;
            toggle_clk_div <= toggle_clk_div; 
        end
    end
end

assign clk_div = toggle_clk_div;

endmodule
